import os

class SecurityClient:
    def __init__(self, key_vault_url: str = None):
        if key_vault_url is None:
            self.key_vault_url = os.environ.get("AZURE_KEY_VAULT_URL")
            if not self.key_vault_url:
                raise ValueError("AZURE_KEY_VAULT_URL environment variable not set.")
        else:
            self.key_vault_url = key_vault_url
        self.credential = DefaultAzureCredential()

    def get_key_client(self) -> KeyClient:
        return KeyClient(vault_url=self.key_vault_url, credential=self.credential)

    def get_cryptography_client(self, key_id: str) -> CryptographyClient:
        return CryptographyClient(key_id=key_id, credential=self.credential)

from azure.identity import DefaultAzureCredential
from azure.keyvault.keys.crypto import CryptographyClient, EncryptionAlgorithm
from security_models import DecryptionRequest, DecryptionResponse

def decrypt_payload(request: DecryptionRequest, config=None) -> DecryptionResponse:
    config = config or {}
    with DefaultAzureCredential() as credential:
        with CryptographyClient(request.key_id, credential=credential) as client:
            response = client.decrypt(request.algorithm, request.ciphertext, iv=request.iv, authentication_tag=request.tag)
    return DecryptionResponse(plaintext=response.plaintext, key_id=response.key_id, algorithm=request.algorithm)

from azure.ai.contentsafety import ContentSafetyClient
from azure.ai.contentsafety.models import AnalyzeTextOptions, TextCategory
from azure.core.credentials import AzureKeyCredential
import os

def check_payload_safety(decrypted_text: str, endpoint: str = None, key: str = None) -> dict:
    if not endpoint:
        endpoint = os.environ.get("AZURE_CONTENT_SAFETY_ENDPOINT")
        if not endpoint:
            raise ValueError("AZURE_CONTENT_SAFETY_ENDPOINT environment variable not set.")
    if not key:
        key = os.environ.get("AZURE_CONTENT_SAFETY_KEY")
        if not key:
            raise ValueError("AZURE_CONTENT_SAFETY_KEY environment variable not set.")

    client = ContentSafetyClient(endpoint, AzureKeyCredential(key))

    # Define categories to analyze
    categories = [
        TextCategory.HATE_SPEECH,
        TextCategory.SEXUAL,
        TextCategory.SELF_HARM,
        TextCategory.VIOLENCE,
    ]
    request = AnalyzeTextOptions(text=decrypted_text, categories=categories)

    response = client.analyze_text(request)

    safety_results = {"violations": []}
    for category_result in response.categories_analysis:
        if category_result.severity is not None and category_result.severity > 0:
            safety_results["violations"].append({
                "category": category_result.category.value,
                "severity": category_result.severity
            })

    return safety_results

from openai import AzureOpenAI
import os

def embed_audit_note(audit_note: str, 
                     azure_openai_endpoint: str = None, 
                     azure_openai_key: str = None, 
                     azure_openai_deployment_name: str = None) -> list[float]:

    if not azure_openai_endpoint:
        azure_openai_endpoint = os.environ.get("AZURE_OPENAI_ENDPOINT")
        if not azure_openai_endpoint:
            raise ValueError("AZURE_OPENAI_ENDPOINT environment variable not set.")
    if not azure_openai_key:
        azure_openai_key = os.environ.get("AZURE_OPENAI_KEY")
        if not azure_openai_key:
            raise ValueError("AZURE_OPENAI_KEY environment variable not set.")
    if not azure_openai_deployment_name:
        azure_openai_deployment_name = os.environ.get("AZURE_OPENAI_EMBEDDING_DEPLOYMENT_NAME")
        if not azure_openai_deployment_name:
            raise ValueError("AZURE_OPENAI_EMBEDDING_DEPLOYMENT_NAME environment variable not set.")

    client = AzureOpenAI(
        azure_endpoint = azure_openai_endpoint,
        api_key = azure_openai_key,
        api_version = "2024-02-01"
    )

    response = client.embeddings.create(
        input=audit_note,
        model=azure_openai_deployment_name # Use the deployment name for Azure OpenAI
    )
    return response.data[0].embedding
